package com.autojobapply;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.WaitUntilState;
public final class PlaywrightSmokeTest { public static void main(String[] args) { long start=System.nanoTime(); try(Playwright p=Playwright.create(); Browser b=p.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true))){System.out.println("LAUNCH_PASSED");Page page=b.newPage();page.navigate("data:text/html,<title>Local</title><p>ok</p>",new Page.NavigateOptions().setWaitUntil(WaitUntilState.DOMCONTENTLOADED).setTimeout(5000));System.out.println("LOCAL_NAVIGATION_PASSED");try{page.navigate("https://example.com",new Page.NavigateOptions().setWaitUntil(WaitUntilState.DOMCONTENTLOADED).setTimeout(10000));System.out.println("HTTPS_NAVIGATION_PASSED");}catch(Exception e){System.out.println("HTTPS_NAVIGATION_FAILED: "+e.getMessage());}}catch(Exception e){System.out.println("PLAYWRIGHT_FAILED: "+e.getMessage());}finally{System.out.println("ELAPSED_MS="+((System.nanoTime()-start)/1_000_000));}} }
